                {
                    title: "Actions",
                    formatter: () => {
                        return '<button class="btn btn-sm btn-outline-primary">Edit</button>';
                    },
                    headerSort: false,
                    hozAlign: "center"
                }
            ],
            initialSort: [{ column: "name", dir: "asc" }]
